<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);$type=(string)($_GET['type']??'scoring');$place=(string)($_GET['place']??'');$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.id=:id");$s->execute(['id'=>$roundId]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Test round not found.');}$title=strtoupper(str_replace('_',' ',$type));$items=[];if($type==='judges'){$s=$pdo->prepare("SELECT judge_name,judge_order,is_chief,scoring_scope FROM bdc_test_scoring_judges WHERE round_id=:r ORDER BY judge_order");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif(in_array($type,['callbacks','finalists'],true)){$s=$pdo->prepare("SELECT se.display_name,se.bib_number,se.dance_role,sr.rank_number FROM bdc_test_scoring_results sr JOIN bdc_test_scoring_entries se ON se.id=sr.entry_id WHERE sr.round_id=:r AND sr.result_status IN('callback','alternate') ORDER BY sr.rank_number");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif(in_array($type,['winners','results'],true)){try{$s=$pdo->prepare("SELECT fr.final_rank,le.display_name leader_name,fe.display_name follower_name FROM bdc_test_scoring_final_results fr JOIN bdc_test_scoring_final_pairs fp ON fp.id=fr.pair_id JOIN bdc_test_scoring_entries le ON le.id=fp.leader_entry_id LEFT JOIN bdc_test_scoring_entries fe ON fe.id=fp.follower_entry_id WHERE fr.round_id=:r AND fr.final_rank<=5 ORDER BY fr.final_rank");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}catch(Throwable){$items=[];}if($place!==''&&$place!=='all')$items=array_values(array_filter($items,fn($x)=>(int)$x['final_rank']===(int)$place));}else{try{$s=$pdo->prepare("SELECT COUNT(*) total,SUM(CASE WHEN status='submitted' THEN 1 ELSE 0 END) submitted FROM bdc_test_scoring_judge_sessions WHERE round_id=:r");$s->execute(['r'=>$roundId]);$items=[$s->fetch()?:['total'=>0,'submitted'=>0]];}catch(Throwable){$items=[['total'=>0,'submitted'=>0]];}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TEST <?=e($title)?></title><style>*{box-sizing:border-box}html,body{margin:0;height:100%;background:#05070b;color:#fff;font-family:Arial,sans-serif}.stage{height:100vh;max-width:56.25vh;margin:auto;background:radial-gradient(circle at top,#4a101e,#111827 50%,#030509);padding:4vh 3vh;text-align:center}.test{background:#ffc107;color:#111;font-weight:900;padding:1vh;border-radius:1vh}.event{font-size:2.3vh;font-weight:900;margin-top:2vh}.meta{font-size:1.4vh;color:#ffb7c3;margin-top:1vh}.title{font-size:4vh;font-weight:900;margin:4vh 0 3vh}.list{display:flex;flex-direction:column;gap:1.4vh}.item{background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.2);border-radius:2vh;padding:2vh;font-size:2.2vh}.big{font-size:9vh;font-weight:900}.place{font-size:5vh;font-weight:900;color:#ffd966}.small{font-size:1.5vh;color:#cbd5e1}</style></head><body><div class="stage"><div class="test">TEST MODE</div><div class="event"><?=e($r['event_name'])?></div><div class="meta"><?=e(strtoupper(str_replace('_',' ',$r['division'])))?> · <?=e(strtoupper($r['round_type']))?></div><div class="title"><?=e($title)?></div><div class="list"><?php if($type==='scoring'):$x=$items[0];?><div class="item"><div class="big"><?=(int)($x['submitted']??0)?> / <?=(int)($x['total']??0)?></div><div class="small">JUDGES SUBMITTED</div></div><?php elseif($type==='judges'):foreach($items as $x):?><div class="item"><?=e($x['judge_name'])?><?=(int)$x['is_chief']?' ★':''?></div><?php endforeach;elseif(in_array($type,['winners','results'],true)):foreach($items as $x):?><div class="item"><div class="place">#<?=(int)$x['final_rank']?></div><?=e($x['leader_name'])?><?=!empty($x['follower_name'])?' & '.e($x['follower_name']):''?></div><?php endforeach;else:foreach($items as $x):?><div class="item"><?=e($x['display_name'])?><div class="small"><?=e(strtoupper($x['dance_role']))?> · <?=!empty($x['bib_number'])?'BIB '.(int)$x['bib_number']:'BIB UNASSIGNED'?></div></div><?php endforeach;endif;?></div></div></body></html>